    private static Vocabulary v(String word, String ipaUk, String ipaUs, String type,
                                 String meaningVi, String contextMeaningVi,
                                 String exampleEn, String exampleVi,
                                 String collocations, String commonMistake,
                                 String level, String topic) {
        Vocabulary vocab = new Vocabulary();
        vocab.setWord(word);
        vocab.setIpaUk(ipaUk);
        vocab.setIpaUs(ipaUs);
        vocab.setType(type);
        vocab.setMeaningVi(meaningVi);
        vocab.setContextMeaningVi(contextMeaningVi);
        vocab.setExampleEn(exampleEn);
        vocab.setExampleVi(exampleVi);
        vocab.setCollocations(collocations);
        vocab.setCommonMistake(commonMistake);
        vocab.setLevel(level);
        vocab.setTopic(topic);
        return vocab;
    }
